import{_ as e,o as l,c as a,a2 as d}from"./chunks/framework.DQhM5RF8.js";const g=JSON.parse('{"title":"Master Commands Reference","description":"","frontmatter":{},"headers":[],"relativePath":"info/commands.md","filePath":"info/commands.md"}'),o={name:"info/commands.md"};function n(r,t,s,i,c,y){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="master-commands-reference" tabindex="-1">Master Commands Reference <a class="header-anchor" href="#master-commands-reference" aria-label="Permalink to &quot;Master Commands Reference&quot;">​</a></h1><p>Quick reference of essential player commands available on LlamaCraft.</p><hr><h2 id="_1-navigation-teleportation" tabindex="-1">1. Navigation &amp; Teleportation <a class="header-anchor" href="#_1-navigation-teleportation" aria-label="Permalink to &quot;1. Navigation &amp; Teleportation&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/menu</code></td><td style="text-align:left;">Opens the master interactive server GUI menu</td><td style="text-align:left;">Bedrock &amp; Java compatible</td></tr><tr><td style="text-align:left;"><code>/spawn</code></td><td style="text-align:left;">Teleports to the survival hub spawn</td><td style="text-align:left;">3-second combat warmup</td></tr><tr><td style="text-align:left;"><code>/tpa &lt;player&gt;</code></td><td style="text-align:left;">Sends a teleport request to another player</td><td style="text-align:left;">Expires after 60 seconds</td></tr><tr><td style="text-align:left;"><code>/tpaccept</code></td><td style="text-align:left;">Accepts the most recent teleport request</td><td style="text-align:left;">Cancelled if moving during warmup</td></tr><tr><td style="text-align:left;"><code>/tpdeny</code></td><td style="text-align:left;">Denies a pending teleport request</td><td style="text-align:left;">Silent rejection</td></tr><tr><td style="text-align:left;"><code>/sethome [name]</code></td><td style="text-align:left;">Sets a private teleport waypoint at your location</td><td style="text-align:left;">Default limit: 3 homes</td></tr><tr><td style="text-align:left;"><code>/home [name]</code></td><td style="text-align:left;">Teleports to your saved waypoint</td><td style="text-align:left;">Cancelled on incoming damage</td></tr><tr><td style="text-align:left;"><code>/back</code></td><td style="text-align:left;">Returns to your previous death or teleport point</td><td style="text-align:left;">5-minute cooldown</td></tr><tr><td style="text-align:left;"><code>/rtp</code></td><td style="text-align:left;">Randomly teleports to safe wilderness coordinates</td><td style="text-align:left;">Minimum 1,500 blocks from spawn</td></tr></tbody></table><hr><h2 id="_2-land-protection-griefprevention" tabindex="-1">2. Land Protection (GriefPrevention) <a class="header-anchor" href="#_2-land-protection-griefprevention" aria-label="Permalink to &quot;2. Land Protection (GriefPrevention)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/claim</code></td><td style="text-align:left;">Creates a new claim box (requires golden shovel)</td><td style="text-align:left;">Set two opposite corners</td></tr><tr><td style="text-align:left;"><code>/trust &lt;player&gt;</code></td><td style="text-align:left;">Grants full build and chest access to a player</td><td style="text-align:left;">Works across whole claim</td></tr><tr><td style="text-align:left;"><code>/containertrust &lt;player&gt;</code></td><td style="text-align:left;">Grants chest, hopper, furnace, and inventory access</td><td style="text-align:left;">Cannot break or place blocks</td></tr><tr><td style="text-align:left;"><code>/accesstrust &lt;player&gt;</code></td><td style="text-align:left;">Grants button, lever, and door access</td><td style="text-align:left;">For public base visitors</td></tr><tr><td style="text-align:left;"><code>/untrust &lt;player&gt;</code></td><td style="text-align:left;">Revokes all permissions from a player</td><td style="text-align:left;">Immediate effect</td></tr><tr><td style="text-align:left;"><code>/abandonclaim</code></td><td style="text-align:left;">Deletes the claim you are currently standing inside</td><td style="text-align:left;">Refunds claim blocks</td></tr><tr><td style="text-align:left;"><code>/claimslist</code></td><td style="text-align:left;">Displays all your active claims and remaining claim blocks</td><td style="text-align:left;">Lists coordinates</td></tr></tbody></table><hr><h2 id="_3-economy-player-markets" tabindex="-1">3. Economy &amp; Player Markets <a class="header-anchor" href="#_3-economy-player-markets" aria-label="Permalink to &quot;3. Economy &amp; Player Markets&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/bal</code> or <code>/balance</code></td><td style="text-align:left;">Displays your current wallet balance</td><td style="text-align:left;">Formats with k/m/b suffixes</td></tr><tr><td style="text-align:left;"><code>/pay &lt;player&gt; &lt;amount&gt;</code></td><td style="text-align:left;">Transfers funds directly to another player</td><td style="text-align:left;">Supports shorthand (<code>/pay Steve 50k</code>)</td></tr><tr><td style="text-align:left;"><code>/shop</code></td><td style="text-align:left;">Opens the server item marketplace GUI</td><td style="text-align:left;">Buy and sell basic commodities</td></tr><tr><td style="text-align:left;"><code>/ah</code></td><td style="text-align:left;">Opens the global player auction house</td><td style="text-align:left;">Search by enchant, tool, or player</td></tr><tr><td style="text-align:left;"><code>/ah sell &lt;price&gt;</code></td><td style="text-align:left;">Lists the item in your main hand on the auction house</td><td style="text-align:left;">48-hour expiration</td></tr></tbody></table><hr><h2 id="_4-voice-chat-combat" tabindex="-1">4. Voice Chat &amp; Combat <a class="header-anchor" href="#_4-voice-chat-combat" aria-label="Permalink to &quot;4. Voice Chat &amp; Combat&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/voice</code> or <code>/audio</code></td><td style="text-align:left;">Generates your private proximity audio web link</td><td style="text-align:left;">For Bedrock &amp; mobile players</td></tr><tr><td style="text-align:left;"><code>/duel &lt;player&gt;</code></td><td style="text-align:left;">Challenges a player to an arena duel</td><td style="text-align:left;">Preserves survival inventory</td></tr><tr><td style="text-align:left;"><code>/duel accept &lt;player&gt;</code></td><td style="text-align:left;">Accepts an arena duel invitation</td><td style="text-align:left;">Teleports to duel stadium</td></tr></tbody></table>',14)])])}const m=e(o,[["render",n]]);export{g as __pageData,m as default};
